// === Tab: mySketch ===
const sketch = (p) => {
	// Framebuffer objects for the ping-pong technique.
	// fboA will hold the result of the previous frame.
	// fboB will be where we draw the current frame.
	let fboA, fboB;

	// The shader that will apply the blur and fade effect.
	let fadeShader;
	// The shader that colorizes the text image.
	let colorizeShader;
	let colorizePaletteShader;

	// The image containing the text to be displayed.
	let textImage;

	// --- Effect Parameters ---
	// Controls how much the previous frame's color is preserved.
	// A value close to 1.0 creates long, persistent trails.
	// A lower value makes the trails fade out more quickly.
	const fadeAmount = 0.998; // Adjustable delta amount

	// Controls the radius of the box blur. An integer.
	// 1 = 3x3 blur, 2 = 5x5 blur, etc.
	// Larger values create a more diffuse, spread-out effect but are more GPU-intensive.
	const blurRadius = 5; // e.g. 1 = 3x3 blur, 2 = 5x5 blur

	p.preload = function () {
		// Load the shader files. p5.js automatically handles compiling them.
		fadeShader = p.createShader(passthru_vert, fade_frag);
		colorizeShader = p.createShader(passthru_vert, colorize_frag);

		// Load the image that contains the text.
		textImage = p.loadImage('https://openprocessing.org/sketch/2693962/files/IMG_1868.JPG');
	};

	p.setup = function () {
		// Set up the canvas in WEBGL mode to enable GPU acceleration and shaders.
		p.createCanvas(920, 690, p.WEBGL);
		p.noCursor(); // Hide the mouse cursor for a cleaner look.

		// Define options for the framebuffers.
		// `format: p.FLOAT` is essential for smooth feedback effects. It uses a
		// higher precision color format (32-bit float vs 8-bit int) which prevents
		// rounding errors from accumulating and allows colors to fade smoothly to zero.
		const fboOptions = { format: p.FLOAT, textureFiltering: p.NEAREST };
		fboA = p.createFramebuffer(fboOptions);
		fboB = p.createFramebuffer(fboOptions);

		// Clear both FBOs to a neutral state (black) at the start.
		// This ensures we don't start with uninitialized garbage data.
		[fboA, fboB].forEach(fbo => {
			fbo.begin();
			p.background(0);
			fbo.end();
		});
	};

	p.draw = function () {
		if (p.frameCount%200==0) p.save("img_" + p.month() + '-' + p.day() + '_' + p.hour() + '-' + p.minute() + '-' + p.second() + ".jpg");
		fboB.begin();

		fadeShader.setUniform('textureSampler', fboA.color);
		fadeShader.setUniform('fadeAmount', fadeAmount);

		fadeShader.setUniform('texelSize', [1.0 / p.width, 1.0 / p.height]);
		fadeShader.setUniform('blurRadius', blurRadius);

		// Apply the shader.
		p.shader(fadeShader);

		p.noStroke();
		p.rect(-p.width / 2, -p.height / 2, p.width, p.height);

		p.resetShader();

		const currentShader = colorizeShader;
		p.shader(currentShader);
		currentShader.setUniform('textImage', textImage);
		currentShader.setUniform('time', p.frameCount / 60.0);
		currentShader.setUniform('resolution', [p.width, p.height]);

		p.rect(-p.width / 2, -p.height / 2, p.width, p.height);

		p.resetShader();

		fboB.end();

		p.background(0);
		p.image(fboB.color, -p.width / 2, -p.height / 2, p.width, p.height);

		let temp = fboA;
		fboA = fboB;
		fboB = temp;
	};
};

new p5(sketch); 

// === Tab: passthru_vert ===
let passthru_vert = `#version 300 es

in vec3 aPosition;
in vec2 aTexCoord;

out vec2 vTexCoord;

uniform mat4 uProjectionMatrix;
uniform mat4 uModelViewMatrix;

void main() {
  gl_Position = uProjectionMatrix * uModelViewMatrix * vec4(aPosition, 1.0);
  vTexCoord = aTexCoord;
}`

// === Tab: fade_frag ===
let fade_frag = `#version 300 es
#ifdef GL_ES
precision mediump float;
#endif

in vec2 vTexCoord;
uniform sampler2D textureSampler;

// The multiplicative factor for fading. 0.99 means "keep 99% of the color".
uniform float fadeAmount;

// The size of a single pixel (texel) in UV coordinates (0.0-1.0).
uniform vec2 texelSize;

// The radius of the box blur, as an integer. 1 = 3x3, 2 = 5x5, etc.
uniform int blurRadius;

out vec4 fragColor;

void main() {
  vec4 totalColor = vec4(0.0);

  // --- Box Blur Logic ---
  // Iterate in a square grid around the current pixel, from -radius to +radius.
  for (int x = -blurRadius; x <= blurRadius; x++) {
    for (int y = -blurRadius; y <= blurRadius; y++) {
      // Calculate the UV coordinate of the neighboring pixel to sample.
      vec2 offset = vec2(float(x), float(y)) * texelSize;

      totalColor += texture(textureSampler, vTexCoord + offset);
    }
  }

  // --- Averaging and Fading ---
  float totalSamples = (float(blurRadius) * 2.0 + 1.0) * (float(blurRadius) * 2.0 + 1.0);
  vec4 blurredColor = totalColor / totalSamples;

  blurredColor.rgb *= fadeAmount;

  fragColor = blurredColor;
}`

// === Tab: colorize_frag ===
let colorize_frag = `#version 300 es
precision highp float;

in vec2 vTexCoord;

uniform sampler2D textImage; // The white-on-transparent text image.
uniform float time;          // A continuously increasing time value.
uniform vec2 resolution;     // The dimensions of the canvas.

out vec4 fragColor;

void main() {
    const float margin = 0.1;

    if (vTexCoord.x < margin || vTexCoord.x > 1.0 - margin || vTexCoord.y < margin || vTexCoord.y > 1.0 - margin) {
        fragColor = vec4(0.0, 0.0, 0.0, 0.0);
    } else {
        vec2 remappedTexCoord = (vTexCoord - margin) / (1.0 - 2.0 * margin);
        vec4 imageColor = texture(textImage, remappedTexCoord);

        if (imageColor.a > 0.1) {
            vec2 pos = gl_FragCoord.xy / resolution.xy;

            float r = 0.7 + 0.3 * cos(time * 1.0 + pos.x * 5.0 + pos.y * 1.5);
            float g = 0.7 + 0.3 * sin(time * 2.0 + pos.x * 3.0 - pos.y * 2.5);
            float b = 0.7 + 0.3 * cos(time * 4.0 + pos.y * 4.0 + pos.x * 3.0);

            fragColor = vec4(r, g, b, imageColor.a);
        } else {
            fragColor = vec4(0.0, 0.0, 0.0, 0.0);
        }
    }
}`

